import sys

def main():
    # Read all input and concatenate into a single string
    s = ''.join([line for line in sys.stdin])

    # Extract all tags from the string
    tags = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '<':
            j = i + 1
            while j < n and s[j] != '>':
                j += 1
            if j >= n:
                break  # According to problem statement, this won't happen
            tag = s[i:j+1]
            tags.append(tag)
            i = j + 1
        else:
            i += 1

    # Stack to keep track of each table's context
    stack = []
    results = []

    for tag in tags:
        if tag == '<table>':
            # Push new table context
            stack.append({'total': 0, 'current_row': 0})
        elif tag == '</table>':
            # Pop the table and record its size
            if stack:
                info = stack.pop()
                results.append(info['total'])
        elif tag == '<tr>':
            # Start a new row in the current table
            if stack:
                stack[-1]['current_row'] = 0
        elif tag.startswith('<td>'):
            # Increment the current row count for the table
            if stack:
                stack[-1]['current_row'] += 1
        elif tag == '</tr>':
            # Close the row: add to total and reset current row
            if stack:
                info = stack[-1]
                info['total'] += info['current_row']
                info['current_row'] = 0

    # Sort the results and print
    results.sort()
    print(' '.join(map(str, results)))

